// CloudtainerML rev0016: 1-bit scaffold + low-rank correction probe for SSM-like transitions.
// Inspired by Density Field State Space Models. We test whether binary sign
// scaffold plus small low-rank correction can preserve synthetic recurrent
// transition behavior better than plain binary or int8 under equal-ish budgets.

#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <numeric>
#include <random>
#include <string>
#include <vector>
struct Mat{int n=0; std::vector<double>a; Mat(){} Mat(int n_):n(n_),a(n_*n_,0){} double&operator()(int i,int j){return a[i*n+j];} double operator()(int i,int j)const{return a[i*n+j];}};
struct Vec{std::vector<double>x;}; struct Row{std::string regime,method;int rank=0;double rel_state_error=0,sign_agreement=0,bytes_proxy=0;int n=0;};
static std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"')o+="\\\"";else if(c=='\\')o+="\\\\";else o+=c;}return o;}
static double dot(const Vec&a,const Vec&b){double s=0;for(size_t i=0;i<a.x.size();i++)s+=a.x[i]*b.x[i];return s;} static double norm(const Vec&a){return std::sqrt(std::max(1e-30,dot(a,a)));}
static Vec mv(const Mat&A,const Vec&x){Vec y; y.x.assign(A.n,0); for(int i=0;i<A.n;i++)for(int j=0;j<A.n;j++)y.x[i]+=A(i,j)*x.x[j]; return y;} static Vec tanhvec(Vec y){for(double&v:y.x)v=std::tanh(v); return y;}
static Mat make(std::mt19937_64&r,const std::string&reg,int n){std::normal_distribution<double>N(0,1.0/std::sqrt(n)); Mat A(n); for(double&v:A.a)v=N(r); if(reg=="lowrank_plus_noise"){std::vector<double>u(n),v(n);for(int i=0;i<n;i++){u[i]=N(r);v[i]=N(r);} for(int i=0;i<n;i++)for(int j=0;j<n;j++)A(i,j)+=1.8*u[i]*v[j];} if(reg=="blocky_phases"){for(int i=0;i<n;i++)for(int j=0;j<n;j++) if(i/8==j/8) A(i,j)+=0.18;} if(reg=="rare_direction"){int d=n-3; for(int j=0;j<n;j++)A(d,j)+=0.35*N(r); for(int i=0;i<n;i++)A(i,d)+=0.20*N(r);} double scale=0;for(double z:A.a)scale+=z*z; scale=std::sqrt(scale/n); for(double&z:A.a)z*=0.82/std::max(1e-9,scale); return A;}
static Mat sign_scaffold(const Mat&A){Mat B(A.n); double m=0;for(double z:A.a)m+=std::abs(z); m/=A.a.size(); for(size_t i=0;i<A.a.size();i++)B.a[i]=(A.a[i]>=0?m:-m); return B;} static Mat int8_quant(const Mat&A){Mat B(A.n); double mx=0;for(double z:A.a)mx=std::max(mx,std::abs(z)); for(size_t i=0;i<A.a.size();i++){double q=std::round(A.a[i]/mx*127); q=std::max(-127.0,std::min(127.0,q)); B.a[i]=q/127*mx;} return B;}
static Mat residual_rank(const Mat&A,const Mat&B,int rank){int n=A.n; Mat R(n); for(int i=0;i<n;i++)for(int j=0;j<n;j++)R(i,j)=A(i,j)-B(i,j); Mat C=B; // crude power-iteration rank-1 deflation, enough for toy
 std::mt19937_64 rng(123+rank*17+n); std::normal_distribution<double>N(0,1); for(int rr=0;rr<rank;rr++){std::vector<double>v(n);for(double&z:v)z=N(rng); for(int it=0;it<12;it++){std::vector<double>u(n,0),nv(n,0); for(int i=0;i<n;i++)for(int j=0;j<n;j++)u[i]+=R(i,j)*v[j]; double un=0;for(double z:u)un+=z*z; un=std::sqrt(un)+1e-12; for(double&z:u)z/=un; for(int j=0;j<n;j++)for(int i=0;i<n;i++)nv[j]+=R(i,j)*u[i]; double vn=0;for(double z:nv)vn+=z*z; vn=std::sqrt(vn)+1e-12; for(int j=0;j<n;j++)v[j]=nv[j]/vn;} std::vector<double>u(n,0); for(int i=0;i<n;i++)for(int j=0;j<n;j++)u[i]+=R(i,j)*v[j]; double sigma=0;for(double z:u)sigma+=z*z; sigma=std::sqrt(sigma); if(sigma<1e-9)break; for(double&z:u)z/=sigma; for(int i=0;i<n;i++)for(int j=0;j<n;j++){double add=sigma*u[i]*v[j]; C(i,j)+=add; R(i,j)-=add;}}
 return C;}
static Row eval(std::mt19937_64&r,const std::string&reg,const std::string&method,int rank){int n=48,T=32; Mat A=make(r,reg,n),B; double bytes=0; if(method=="fp32_teacher"){B=A;bytes=4*n*n;} else if(method=="int8_full"){B=int8_quant(A);bytes=1*n*n;} else if(method=="binary_scaffold"){B=sign_scaffold(A);bytes=0.125*n*n;} else if(method=="binary_plus_lowrank"){Mat S=sign_scaffold(A);B=residual_rank(A,S,rank);bytes=0.125*n*n+2.0*rank*n;} else {B=int8_quant(A);bytes=n*n;} std::normal_distribution<double>N(0,1); Vec x,y; x.x.resize(n); for(double&z:x.x)z=N(r); y=x; for(int t=0;t<T;t++){x=tanhvec(mv(A,x)); y=tanhvec(mv(B,y));} Vec d; d.x.resize(n); int same=0; for(int i=0;i<n;i++){d.x[i]=x.x[i]-y.x[i]; if((x.x[i]>=0)==(y.x[i]>=0))same++;} Row row; row.regime=reg; row.method=method; row.rank=rank; row.rel_state_error=norm(d)/std::max(1e-12,norm(x)); row.sign_agreement=(double)same/n; row.bytes_proxy=bytes; row.n=1; return row;}
static void acc(Row&a,const Row&b){a.rel_state_error+=b.rel_state_error;a.sign_agreement+=b.sign_agreement;a.bytes_proxy+=b.bytes_proxy;a.n++;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0016_DFSSM_QUANT_SCAFFOLD_SMOKE.json"; if(argc>1)out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string>regs={"random_dense","lowrank_plus_noise","blocky_phases","rare_direction"}; std::vector<std::string>methods={"fp32_teacher","int8_full","binary_scaffold","binary_plus_lowrank"}; std::vector<int>ranks={0,2,4,8}; std::map<std::string,Row>rows; std::map<std::string,int>winners; for(int seed=0;seed<24;seed++){std::mt19937_64 rng(9911+seed*13); for(auto&reg:regs){double best=1e99;std::string win; for(auto&m:methods)for(int rk:ranks){if(m!="binary_plus_lowrank"&&rk!=0)continue; Row x=eval(rng,reg,m,rk); std::string key=reg+"|"+m+"|"+std::to_string(rk); if(!rows.count(key)){rows[key]=x; rows[key].rel_state_error=rows[key].sign_agreement=rows[key].bytes_proxy=0; rows[key].n=0;} acc(rows[key],x); double score=x.rel_state_error + 0.000002*x.bytes_proxy; if(score<best){best=score;win=m+(m=="binary_plus_lowrank"?"_r"+std::to_string(rk):"");}} winners[win]++;}}
 double sec=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0016\",\n  \"probe\": \"dfssm_quant_scaffold\",\n  \"config\": {\"seeds\": 24, \"state_dim\": 48, \"steps\": 32},\n  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<sec<<", \"primary_metric\": {\"name\": \"mean_rel_state_error\", \"direction\": \"lower_is_better\", \"winner_field\": \"regularized_winner_counts\"}, \"regularized_winner_counts\": {"; bool first=true; for(auto&kv:winners){if(!first)f<<", "; first=false; f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto r=kv.second; double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"method\": \""<<esc(r.method)<<"\", \"rank\": "<<r.rank<<", \"mean_rel_state_error\": "<<r.rel_state_error/n<<", \"mean_sign_agreement\": "<<r.sign_agreement/n<<", \"mean_bytes_proxy\": "<<r.bytes_proxy/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n";}
